var t=[{title:`Substituts possibles`,text:`Un sac à dos fermé dont le contenu est réparti uniformément peut ajouter de la résistance à un squat ou à un portage. Des bouteilles d’eau peuvent servir de poids légers pour les mains, et une marche solide peut remplacer une plateforme d’exercice basse. Ces objets n’ont pas de taille ni de poids standard, donc la charge et l’équilibre peuvent changer sans prévenir.`},{title:`Les meubles sont un risque majeur`,text:`Une chaise de salle à manger peut glisser ou basculer pendant des dips, des montées sur marche ou des pompes inclinées, et beaucoup de tables ne peuvent pas supporter un rowing au poids du corps tiré sous le bord. Ne supposez jamais qu’une table ordinaire, une serviette, une poignée de porte ou une étagère peut supporter le poids de votre corps. Si une installation dépend d’une solidité ou d’un ancrage dont vous n’êtes pas sûr, choisissez un autre exercice.`},{title:`Vérifiez chaque objet`,text:`Assurez-vous que la surface ne glisse pas, que le récipient ne fuit pas et n’a pas de poignées cassées, et que les bretelles du sac à dos ne se déchirent pas. Répartissez le poids pour qu’il ne se balance pas soudainement. Évitez les récipients en verre, les arêtes métalliques coupantes et les piles de livres instables. Entraînez-vous sur un sol dégagé, loin de tout objet fragile.`},{title:`Progressez lentement`,text:`Commencez par un mouvement simple et une petite charge. Des répétitions lentes et reproductibles valent mieux qu’un équilibre difficile. Si vous ne pouvez pas peser l’objet de façon fiable, notez la configuration et une idée approximative de la résistance plutôt qu’un chiffre précis. Gardez chaque augmentation assez petite pour rester en contrôle.`},{title:`Avec TrainUp`,text:`Un objet du quotidien n’est pas un banc, un rack, une barre de traction ou un poste à câble. Dans Profil, saisissez un type de banc ou une barre de traction seulement pour du vrai matériel. Quand vous ne pouvez pas être sûr qu’un meuble est sûr, choisissez des exercices au poids du corps qui n’ont besoin d’aucun appui.`}];var i=[{label:`Mayo Clinic : sécurité et technique en musculation`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Bibliothèque d’exercices de l’ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Prise de position 2026 de l’ACSM`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:t,sources:i};export{n as default,t as sections,i as sources};